const raw = $input.first().json;
const p = raw.body ?? raw;

const system = p.contextPack
  ? JSON.stringify(p.contextPack)
  : 'Follow Adaptive Liquidity / AEON brand voice. No yield promises.';

let user;
if (p.mode === 'rewrite') {
  user = [
    'Rewrite this marketing draft per reviewer feedback.',
    '',
    'Review comment: ' + (p.reviewComment ?? '(none)'),
    'Current title: ' + (p.currentTitle ?? ''),
    'Current body:',
    p.currentBody ?? '',
    '',
    'Channel: ' + (p.channel ?? ''),
    'Type: ' + (p.type ?? ''),
    '',
    'Return ONLY valid JSON (no markdown fences) with keys: title (string, max 200 chars), body (string).'
  ].join('\n');
} else {
  user = [
    'Create marketing content for AEON Control Room.',
    '',
    'Channel: ' + (p.channel ?? ''),
    'Type: ' + (p.type ?? ''),
    'Prompt: ' + (p.prompt ?? ''),
    'Title hint: ' + (p.titleHint ?? ''),
    '',
    'Return ONLY valid JSON (no markdown fences) with keys: title (string, max 200 chars), body (string).'
  ].join('\n');
}

return [{ json: { system, user, channel: p.channel, type: p.type } }];

const item = $input.first().json;
let text = '';
if (typeof item.output === 'string') text = item.output;
else if (typeof item.text === 'string') text = item.text;
else if (item.message && typeof item.message.content === 'string') text = item.message.content;
else if (Array.isArray(item.choices) && item.choices[0]?.message?.content) text = item.choices[0].message.content;
else text = JSON.stringify(item);

const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) text = fence[1];
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);

let parsed;
try { parsed = JSON.parse(text); } catch (e) {
  throw new Error('Generate returned non-JSON');
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  throw new Error('Generate returned invalid shape (expected title + body)');
}

const title = parsed.title && String(parsed.title).trim();
const body = parsed.body && String(parsed.body).trim();
if (!title || !body) {
  throw new Error('Generate returned invalid shape (expected title + body)');
}

return [{ json: { title: title.slice(0, 200), body: body.slice(0, 50000) } }];
